INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 1, 'theory', 'Quiz: SSH, tmux and sudo');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 0, 'In sshd_config there is ''PasswordAuthentication no'' higher up and below it a ''Match User backup'' block with ''PasswordAuthentication yes''. Can backup log in with a password?', '["Yes, Match is always stronger than general lines", "Yes, because the last value wins", "No, the first value found wins", "No, this setting is forbidden inside Match"]', 2, 'In sshd_config the first value found is used for most settings. The line before Match already set no, so the yes in the block is ignored. To allow a password for one user, the Match block must come above the general line.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 1, 'On connect, ssh says the host key of a known server has changed. What is the right first step?', '["Find out over another channel whether the server was reinstalled and what its fingerprint is", "Delete the known_hosts file and connect again", "Set StrictHostKeyChecking no in the config", "Replace your own key with a new one"]', 0, 'A key change happens after a reinstall but may also mean impersonation. Compare the fingerprint over an independent channel and only then remove the old entry with ssh-keygen -R.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 2, 'Which authorized_keys line lets a key in only from 10.0.0.0/8 and forbids port forwarding and a terminal?', '["allow=\"10.0.0.0/8\",restrict ssh-ed25519 AAAA...", "from=10.0.0.0/8 ssh-ed25519 AAAA... no-pty", "restrict ssh-ed25519 AAAA... from=\"10.0.0.0/8\"", "from=\"10.0.0.0/8\",restrict ssh-ed25519 AAAA..."]', 3, 'Options go before the key type, are separated by commas without spaces, and the from value is quoted. Restrict disables forwarding and the terminal at once. Options after the key are just a comment.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 3, 'You are changing sshd_config on a remote server. Which order of actions is safe?', '["Edit, restart, then check the login", "A second session, edit, sshd -t, reload, check with a fresh login", "Edit, close all sessions, restart the service", "Edit and sshd -t, but no reload until the server reboots"]', 1, 'The open second session keeps working across a reload and lets you roll back an error. sshd -t catches syntax, and a fresh login confirms the settings logic did not lock you out.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 4, 'In sudoers ''%sudo ALL=(ALL:ALL) ALL'' comes first and ''ann ALL=(ALL) NOPASSWD: /usr/bin/apt'' below it. Ann is in the group sudo and runs apt. What happens?', '["sudo asks for a password because the group rule is more precise", "sudo refuses because of a conflict between two rules", "sudo asks no password for apt but asks for other commands", "sudo asks no password for any command"]', 2, 'The last matching entry wins. For apt it is Ann''s rule with NOPASSWD, so no password is needed. For other commands only the group rule matches, and a password is needed.');
